//! What each convar does and whether the game still honours it in gameinfo.gi.
//! Data comes from `data/convars.json`, generated by `scripts/gen_convars.py` from Valve's convar dump
//! (GameTracking-Deadlock) plus hand-written notes.

use crate::diff::{Change, SEP};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};
use std::sync::OnceLock;

const DATA: &str = include_str!("../data/convars.json");

#[derive(Deserialize)]
struct Entry {
    default: Option<String>,
    valve: Option<String>,
    note: Option<String>,
    #[serde(default)]
    ignored: bool,
}

#[derive(Deserialize)]
struct Data {
    build: String,
    convars: HashMap<String, Entry>,
}

/// What the preview shows next to a changed convar.
#[derive(Debug, Clone, Serialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct ConvarInfo {
    /// Plain description: the hand-written note, else Valve's own text.
    pub text: Option<String>,
    /// Marked `gameinfo_cannot_override`: setting it in gameinfo.gi does nothing.
    pub ignored: bool,
    pub default: Option<String>,
}

fn data() -> &'static Data {
    static DATA_CELL: OnceLock<Data> = OnceLock::new();
    DATA_CELL.get_or_init(|| serde_json::from_str(DATA).unwrap_or(Data { build: String::new(), convars: HashMap::new() }))
}

/// Game build the data was taken from, e.g. "6812".
pub fn build() -> &'static str {
    &data().build
}

pub fn lookup(name: &str) -> Option<ConvarInfo> {
    data().convars.get(&name.to_ascii_lowercase()).map(|e| ConvarInfo {
        text: e.note.clone().or_else(|| e.valve.clone()),
        ignored: e.ignored,
        default: e.default.clone(),
    })
}

/// Convar name of a flattened gameinfo.gi path, if it sits in the ConVars block.
pub fn convar_of(path: &str) -> Option<&str> {
    let mut parts = path.split(SEP);
    let section = parts.next()?;
    let name = parts.next()?;
    (section.eq_ignore_ascii_case("ConVars") && parts.next().is_none()).then_some(name)
}

/// Info for every known convar among `changes`, keyed by the change's path.
pub fn infos_for(changes: &[Change]) -> BTreeMap<String, ConvarInfo> {
    changes
        .iter()
        .filter_map(|c| convar_of(&c.key).and_then(lookup).map(|i| (c.key.clone(), i)))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_loads_and_knows_common_convars() {
        assert!(!build().is_empty());
        let ssao = lookup("R_SSAO").unwrap();
        assert!(ssao.text.unwrap().contains("Ambient occlusion"));
        assert!(!ssao.ignored);
        assert!(lookup("citadel_player_glow_disabled").unwrap().ignored);
        assert!(lookup("not_a_real_convar").is_none());
    }

    #[test]
    fn only_convars_block_entries_are_convars() {
        assert_eq!(convar_of(&format!("ConVars{SEP}r_ssao")), Some("r_ssao"));
        assert_eq!(convar_of(&format!("RenderSystem{SEP}LowLatency")), None);
        assert_eq!(convar_of("r_ssao"), None);
        let changes = vec![Change { key: format!("ConVars{SEP}r_ssao"), before: None, after: Some("0".into()) }];
        assert_eq!(infos_for(&changes).len(), 1);
    }
}
